import hmac
import hashlib
import base64
import json
import os
import time
from typing import Optional, Dict, Any

# RSA public key used for RS256 verification (loaded from config)
RSA_PUBLIC_KEY = """-----BEGIN PUBLIC KEY-----
MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA2a2rwplBQLHgMH9bDa3b
qW5MjITMagVzOUBD4wEVOCbgFCOaRK5oJ5TIxz5t5kFxrVGUYN1GQFqSI0CXVAB+
