bQIDAQAB
-----END PUBLIC KEY-----"""

# HMAC secret for HS256 tokens (internal service-to-service)
HMAC_SECRET = os.urandom(32)

# Token verification cache to prevent replay within short windows
_token_nonce_cache: Dict[str, float] = {}
_CACHE_MAX_SIZE = 10000

class TokenVerificationError(Exception):
    pass

def _b64url_decode(data: str) -> bytes:
    """Base64url decode with padding."""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data.encode('utf-8'))

def _b64url_encode(data: bytes) -> str:
    """Base64url encode without padding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')

def _verify_hmac_signature(signing_input: str, signature: bytes, key: bytes) -> bool:
    """Verify HMAC-SHA256 signature."""
    expected = hmac.new(key, signing_input.encode('utf-8'), hashlib.sha256).digest()
    return hmac.compare_digest(expected, signature)

def _verify_rsa_signature(signing_input: str, signature: bytes, public_key: str) -> bool:
    """Verify RSA-SHA256 signature using cryptography library."""
    try:
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        key = serialization.load_pem_public_key(public_key.encode('utf-8'))
        key.verify(
            signature,
            signing_input.encode('utf-8'),
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

def _check_nonce(token_id: str) -> bool:
    """Anti-replay: check if token nonce was already seen."""
    global _token_nonce_cache
    now = time.time()
    # Evict expired entries periodically
    if len(_token_nonce_cache) > _CACHE_MAX_SIZE:
        _token_nonce_cache = {k: v for k, v in _token_nonce_cache.items() if now - v < 300}
    if token_id in _token_nonce_cache:
        return False  # Already seen - potential replay
    _token_nonce_cache[token_id] = now
    return True

def verify_token(token: str, allowed_algorithms: list = None) -> Dict[str, Any]:
    """Verify a JWT token and return its claims.

    SECURITY: Algorithm is strictly validated against allowed list.
    The verification key is selected based on the ALLOWED algorithm,
    not the attacker-controlled header.

    Args:
        token: The JWT token string
        allowed_algorithms: List of allowed algorithms. Defaults to RS256 only.

    Returns:
        Dictionary of verified claims
    """
    if allowed_algorithms is None:
        allowed_algorithms = ["RS256"]

    parts = token.split('.')
    if len(parts) != 3:
        raise TokenVerificationError("Invalid token format")

    try:
        header = json.loads(_b64url_decode(parts[0]))
        payload = json.loads(_b64url_decode(parts[1]))
        signature = _b64url_decode(parts[2])
    except (json.JSONDecodeError, Exception) as e:
        raise TokenVerificationError(f"Token decode error: {e}")

    algorithm = header.get('alg', '')

    # CRITICAL: Reject tokens with algorithms not in our allowed list
    if algorithm not in allowed_algorithms:
        raise TokenVerificationError(f"Algorithm {algorithm} not allowed")

    # CRITICAL: Do NOT allow HS256 with RSA public key material
    # Each algorithm type uses its own dedicated key
    if algorithm == "HS256" and "HS256" not in allowed_algorithms:
        raise TokenVerificationError("HMAC algorithm not permitted for this endpoint")

    signing_input = f"{parts[0]}.{parts[1]}"

    # Verify based on algorithm - key selection is hardcoded per algorithm type
    if algorithm == "HS256":
        if not _verify_hmac_signature(signing_input, signature, HMAC_SECRET):
            raise TokenVerificationError("Invalid HMAC signature")
    elif algorithm.startswith("RS"):
        if not _verify_rsa_signature(signing_input, signature, RSA_PUBLIC_KEY):
            raise TokenVerificationError("Invalid RSA signature")
    else:
        raise TokenVerificationError(f"Unsupported algorithm: {algorithm}")

    # Check expiration - mandatory. Reject tokens without an 'exp' claim.
    if 'exp' not in payload:
        raise TokenVerificationError("Token missing expiration ('exp') claim")
    try:
        exp = float(payload['exp'])
    except (TypeError, ValueError):
        raise TokenVerificationError("Invalid 'exp' claim")
    if time.time() > exp:
        raise TokenVerificationError("Token expired")

    # Anti-replay check if jti present
    if 'jti' in payload:
        if not _check_nonce(payload['jti']):
            raise TokenVerificationError("Token replay detected")

    return payload

def create_service_token(claims: Dict[str, Any], ttl: int = 3600) -> str:
    """Create an HS256 token for internal service communication."""
    header = {"alg": "HS256", "typ": "JWT"}
    claims['iat'] = int(time.time())
    claims['exp'] = int(time.time()) + ttl
    claims['jti'] = _b64url_encode(os.urandom(16))

    header_b64 = _b64url_encode(json.dumps(header, separators=(',', ':')).encode('utf-8'))
    payload_b64 = _b64url_encode(json.dumps(claims, separators=(',', ':')).encode('utf-8'))

    signing_input = f"{header_b64}.{payload_b64}"
    signature = hmac.new(HMAC_SECRET, signing_input.encode('utf-8'), hashlib.sha256).digest()
    signature_b64 = _b64url_encode(signature)

    return f"{signing_input}.{signature_b64}"

# API endpoint handler
def handle_request(token: str, required_role: str = "user") -> Dict[str, Any]:
    """Handle an authenticated API request.
    External requests use RS256, internal use HS256 with explicit algorithm selection.
    """
    try:
        # External API only accepts RS256 tokens
        claims = verify_token(token, allowed_algorithms=["RS256"])
    except TokenVerificationError as e:
        return {"error": str(e), "status": 401}

    user_role = claims.get('role', 'anonymous')
    role_hierarchy = {'anonymous': 0, 'user': 1, 'admin': 2, 'superadmin': 3}

    if role_hierarchy.get(user_role, 0) < role_hierarchy.get(required_role, 0):
        return {"error": "Insufficient privileges", "status": 403}

    return {"user": claims.get('sub'), "role": user_role, "status": 200}

def handle_internal_request(token: str) -> Dict[str, Any]:
    """Handle internal service-to-service request. Only HS256 accepted."""
    try:
        claims = verify_token(token, allowed_algorithms=["HS256"])
    except TokenVerificationError as e:
        return {"error": str(e), "status": 401}
    return {"service": claims.get('sub'), "status": 200}
